def search(arr):
    """
    Finds the element that appears only once in a sorted array.

    :param arr: List[int] - A sorted list of integers where all elements except one appear twice.
    :return: int - The element that appears only once.
    """
    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2

        if mid % 2 == 0:
            if arr[mid] == arr[mid + 1]:
                left = mid + 2
            else:
                right = mid
        else:
            if arr[mid] == arr[mid - 1]:
                left = mid + 1
            else:
                right = mid - 1

    return arr[left]
